interface ValidationRejection {
  message: string;
  summary: string[];
}

function formatValidationRejection(toolName: string, errors: ErrorObject[] | null | undefined): ValidationRejection {
  const summary = (errors ?? []).map(formatValidationError);
  if (summary.length === 0) {
    const fallbackMessage = `Input for tool "${toolName}" failed schema validation`;
    return {message: fallbackMessage, summary: [fallbackMessage]};
  }
  return {
    message: `Invalid input for tool "${toolName}": ${summary.join('; ')}`,
    summary,
  };
}

function formatValidationError(validationError: ErrorObject): string {
  if (validationError.keyword === 'required') {
    const missingProperty = readStringParam(validationError.params, 'missingProperty');
    const fieldPath = joinFieldPath(validationError.instancePath, missingProperty);
    return `${fieldPath}: missing required property`;
  }
  const fieldPath = formatInstancePath(validationError.instancePath);
  if (validationError.keyword === 'enum') {
    const allowedValues = readAllowedValues(validationError.params);
    return allowedValues ? `${fieldPath}: must be one of [${allowedValues}]` : `${fieldPath}: must match enum`;
  }
  const constraint = validationError.message ?? `violated ${validationError.keyword} constraint`;
  return `${fieldPath}: ${constraint}`;
}

function readStringParam(params: Record<string, unknown>, key: string): string | undefined {
  const candidate = params[key];
  return typeof candidate === 'string' ? candidate : undefined;
}

function readAllowedValues(params: Record<string, unknown>): string | undefined {
  const allowed = params.allowedValues;
  if (!Array.isArray(allowed) || allowed.length === 0) return undefined;
  return allowed.map(entry => JSON.stringify(entry)).join(', ');
}

function joinFieldPath(instancePath: string, propertyName: string | undefined): string {
  const basePath = formatInstancePath(instancePath);
  if (!propertyName) return basePath;
  return basePath === 'input' ? propertyName : `${basePath}.${propertyName}`;
}

function formatInstancePath(instancePath: string): string {
  if (instancePath.length === 0) return 'input';
  const normalized = instancePath.startsWith('/') ? instancePath.slice(1) : instancePath;
  return normalized.replace(/\//g, '.');
}

